CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name text, locale text NOT NULL DEFAULT 'es', glucose_unit text NOT NULL DEFAULT 'mg/dL', diabetes_type text, target_low numeric, target_high numeric, carb_ratio numeric, correction_factor numeric, consent_analytics boolean NOT NULL DEFAULT false, emergency_data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE glucose_readings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, value numeric NOT NULL CHECK(value > 0), unit text NOT NULL, measured_at timestamptz NOT NULL, context text, notes text, source text NOT NULL DEFAULT 'manual', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insulin_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, insulin_type text NOT NULL, brand text, dose numeric NOT NULL CHECK(dose > 0), administered_at timestamptz NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE meals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, carbohydrates numeric NOT NULL DEFAULT 0, protein numeric NOT NULL DEFAULT 0, fat numeric NOT NULL DEFAULT 0, calories numeric NOT NULL DEFAULT 0, fiber numeric NOT NULL DEFAULT 0, eaten_at timestamptz NOT NULL, notes text, is_favorite boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exercises (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, activity_type text NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes > 0), intensity text NOT NULL, performed_at timestamptz NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, message text NOT NULL, severity text NOT NULL DEFAULT 'info', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE emergency_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, phone text NOT NULL, relationship text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sensor_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, status text NOT NULL DEFAULT 'disconnected', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX glucose_readings_user_measured ON glucose_readings(user_id, measured_at DESC);
